contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(
        uint256 fundingFee_,
        uint256 makerFee_,
        uint256 takerFee_,
        uint256 positionFee_,
        uint256 makerLimit_,
        int128 minRate_,
        int128 maxRate_,
        int128 targetRate_,
        uint128 targetUtilization_,
        uint8 payoffType_,
        uint8 payoffDirection_,
        bytes30 payoffData_
    ) public {
        PayoffDefinition memory expected =
            PayoffDefinition(PayoffDefinitionLib.PayoffType(payoffType_),
                              PayoffDefinitionLib.PayoffDirection(payoffDirection_),
                              payoffData_);

        IProduct.ProductInfo memory info = IProduct.ProductInfo({
            name: "P",
            symbol: "P",
            payoffDefinition: expected,
            oracle: IOracleProvider(address(c)),
            maintenance: UFixed18Lib.ZERO,
            fundingFee: UFixed18.wrap(fundingFee_),
            makerFee: UFixed18.wrap(makerFee_),
            takerFee: UFixed18.wrap(takerFee_),
            positionFee: UFixed18.wrap(positionFee_),
            makerLimit: UFixed18.wrap(makerLimit_),
            utilizationCurve: JumpRateUtilizationCurve({
                minRate: PackedFixed18.wrap(minRate_),
                maxRate: PackedFixed18.wrap(maxRate_),
                targetRate: PackedFixed18.wrap(targetRate_),
                targetUtilization: PackedUFixed18.wrap(targetUtilization_)
            })
        });

        // Initialization may revert depending on supplied parameters; only the
        // successful initialization path is checked below.
        bool initOk;
        try c.initialize(info) {
            initOk = true;
        } catch {
            initOk = false;
        }

        if (initOk) {
            bool closedOk;
            try c.updateClosed(true) {
                closedOk = true;
            } catch {
                closedOk = false;
            }

            PayoffDefinition memory observed = c.payoffDefinition();

            assert(
                uint256(observed.payoffType) == uint256(expected.payoffType) &&
                uint256(observed.payoffDirection) == uint256(expected.payoffDirection) &&
                observed.data == expected.data
            );
        } else {
            assert(true);
        }
    }
}

