        require(amount > 0);
        UFixed18 a = UFixed18Lib.wrap(amount);

        // settle account first so latest version is current
        c.settleAccount(account);

        // read before state
        uint256 versionBefore = c.latestVersion(account);
        Position memory posBefore = c.position(account);

        // deciding call: openMakeFor / positionFee observable through state change
        c.openMakeFor(account, a);

        // after open make, the account must have a pending make position
        PrePosition memory preAfter = c.pre(account);
        Position memory posAfter = c.position(account);

        // the oracle version at which the make was opened is latestVersion
        uint256 v = c.latestVersion();

        assert(
            preAfter.oracleVersion == v &&
            posAfter.maker == posBefore.maker &&
            preAfter.openPosition.maker == a
        );
    }

    receive() external payable {}
}

